CREATE TABLE code_inputs (id TEXT PRIMARY KEY, content_hash TEXT NOT NULL, repository_id TEXT REFERENCES repositories(id), blob_oid TEXT, created_at INTEGER NOT NULL, CHECK ((repository_id IS NULL AND blob_oid IS NULL) OR (repository_id IS NOT NULL AND blob_oid IS NOT NULL)), UNIQUE(repository_id, blob_oid));
CREATE UNIQUE INDEX code_inputs_file_content ON code_inputs(content_hash) WHERE repository_id IS NULL;
CREATE TABLE code_derivations (id TEXT PRIMARY KEY, input_id TEXT NOT NULL REFERENCES code_inputs(id), language TEXT NOT NULL, extractor TEXT NOT NULL, extractor_version TEXT NOT NULL, grammar TEXT NOT NULL, grammar_version TEXT NOT NULL, status TEXT NOT NULL, error_count INTEGER NOT NULL, created_at INTEGER NOT NULL, UNIQUE(input_id, extractor, extractor_version, grammar, grammar_version));
CREATE TABLE code_contexts (input_id TEXT NOT NULL REFERENCES code_inputs(id), path TEXT NOT NULL, commit_oid TEXT, PRIMARY KEY(input_id,path,commit_oid));
CREATE TABLE code_entities (id TEXT PRIMARY KEY, derivation_id TEXT NOT NULL REFERENCES code_derivations(id), kind TEXT NOT NULL, name TEXT, qualified_name TEXT, syntax_path TEXT NOT NULL, parent_syntax_path TEXT, start_byte INTEGER NOT NULL,end_byte INTEGER NOT NULL,start_line INTEGER NOT NULL,start_column INTEGER NOT NULL,end_line INTEGER NOT NULL,end_column INTEGER NOT NULL,signature TEXT,visibility TEXT,is_async INTEGER NOT NULL, UNIQUE(derivation_id,syntax_path));
CREATE TABLE code_imports (id TEXT PRIMARY KEY, derivation_id TEXT NOT NULL REFERENCES code_derivations(id), raw TEXT NOT NULL,target TEXT NOT NULL,alias TEXT,start_byte INTEGER NOT NULL,end_byte INTEGER NOT NULL,start_line INTEGER NOT NULL,start_column INTEGER NOT NULL,end_line INTEGER NOT NULL,end_column INTEGER NOT NULL, UNIQUE(derivation_id,start_byte,end_byte));
